## Why This Is Asked
This question tests understanding of ordering guarantees across a dynamically resizing worker pool, per-entity isolation, and practical backpressure in high-throughput streaming systems.

## Key Concepts
- Per-entity FIFO queues with monotonic sequence numbers for strict ordering
- Global bounded buffer with admission control
- Backpressure discipline that defers or drops lower-priority event kinds when the buffer is saturated
- Dynamic worker pool with consistent entity-to-worker mapping for stability
- Late-event handling policy to maintain liveness without breaking per-entity order

## Code Example
```javascript
class Router {
  constructor(bound, workerPool) {
    this.bound = bound;
    this.workers = workerPool;
    this.globalBuffer = [];
    this.entityQueues = new Map();
    this.entitySeq = new Map();
  }

  route(event) {
    if (this.globalBuffer.length >= this.bound) {
      if (event.priority < HIGH) return this.defer(event);
      this.drop(event);
    }

    const seq = this.entitySeq.get(event.entity_id) ?? 0;
    this.entitySeq.set(event.entity_id, seq + 1);

    if (!this.entityQueues.has(event.entity_id)) {
      this.entityQueues.set(event.entity_id, []);
    }

    this.entityQueues.get(event.entity_id).push({ ...event, seq });
    this.assignWorker(event.entity_id);
  }

  isLate(event) {
    return Date.now() - event.ts > LATENESS_THRESHOLD;
  }

  drop(event) { /* log and discard */ }
  defer(event) { /* requeue with backoff */ }
}
```

## Test Plan
1. **Ordering Guarantee**: Spawn N workers, emit out-of-order events for the same entity, verify output maintains sequence order.
2. **Backpressure**: Fill the buffer and confirm lower-priority events are deferred or dropped while higher-priority events are admitted.
3. **Lateness Drop**: Send events with timestamps older than L; verify they are discarded.
4. **Worker Resize**: Add/remove workers mid-stream and confirm no ordering violations for any entity.
5. **Throughput**: Measure events/sec processed under steady-state load.
6. **Recovery**: Simulate worker failure and verify no events are lost or duplicated.

## Why This Question Is Asked
This tests understanding of per-topic ordering, backpressure mechanisms, dynamic topic management, and safe shutdown in a concurrent dispatcher system.

## Key Concepts
- **Bounded backlog and backpressure**: Prevent memory exhaustion by limiting queue depth and signaling producers when buffers are full
- **Per-topic FIFO with ordering guarantees**: Ensure events within each topic maintain publication order
- **Fair scheduling (round-robin)**: Prevent a high-volume topic from starving others
- **Dynamic topic management**: Support on-the-fly topic creation as new device types appear
- **Cancellation and graceful shutdown**: Safely drain pending work without data loss

## Code Example
```go
package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

type Event struct {
	Topic   string
	Payload string
}

type TopicQueue struct {
	ch     chan Event
	mu     sync.Mutex
	closed bool
}

type Dispatcher struct {
	globalBacklog chan Event
	topicQueues  map[string]*TopicQueue
	workers      int
	wg           sync.WaitGroup
	mu           sync.RWMutex
	ctx          context.Context
	cancel       context.CancelFunc
}

func NewDispatcher(backlogSize, workers int) *Dispatcher {
	ctx, cancel := context.WithCancel(context.Background())
	d := &Dispatcher{
		globalBacklog: make(chan Event, backlogSize),
		topicQueues:  make(map[string]*TopicQueue),
		workers:      workers,
		ctx:          ctx,
		cancel:       cancel,
	}
	return d
}

func (d *Dispatcher) getOrCreateTopic(topic string) *TopicQueue {
	d.mu.Lock()
	defer d.mu.Unlock()
	if q, ok := d.topicQueues[topic]; ok {
		return q
	}
	q := &TopicQueue{ch: make(chan Event, 100)}
	d.topicQueues[topic] = q
	return q
}

func (d *Dispatcher) Enqueue(e Event) error {
	select {
	case d.globalBacklog <- e:
		return nil
	default:
		return fmt.Errorf("backpressure: global backlog full")
	}
}

func (d *Dispatcher) Start() {
	for i := 0; i < d.workers; i++ {
		d.wg.Add(1)
		go d.worker(i)
	}
	go d.dispatcher()
}

func (d *Dispatcher) dispatcher() {
	for {
		select {
		case <-d.ctx.Done():
			return
		case e := <-d.globalBacklog:
			q := d.getOrCreateTopic(e.Topic)
			select {
			case q.ch <- e:
			default:
				fmt.Printf("backpressure: topic %s full\n", e.Topic)
			}
		}
	}
}

func (d *Dispatcher) worker(id int) {
	defer d.wg.Done()
	for {
		select {
		case <-d.ctx.Done():
			return
		default:
		}
		d.mu.RLock()
		topics := make([]string, 0, len(d.topicQueues))
		for t := range d.topicQueues {
			topics = append(topics, t)
		}
		d.mu.RUnlock()
		if len(topics) == 0 {
			time.Sleep(time.Millisecond)
			continue
		}
		for _, topic := range topics {
			d.mu.RLock()
			q, ok := d.topicQueues[topic]
			d.mu.RUnlock()
			if !ok {
				continue
			}
			select {
			case e := <-q.ch:
				fmt.Printf("worker %d processed: %s -> %s\n", id, e.Topic, e.Payload)
			default:
			}
		}
	}
}

func (d *Dispatcher) Shutdown() {
	d.cancel()
	d.wg.Wait()
	d.mu.Lock()
	defer d.mu.Unlock()
	for _, q := range d.topicQueues {
		close(q.ch)
	}
}

func main() {
	d := NewDispatcher(1000, 3)
	d.Start()

	d.Enqueue(Event{Topic: "temperature", Payload: "25.5"})
	d.Enqueue(Event{Topic: "humidity", Payload: "60%"})
	d.Enqueue(Event{Topic: "temperature", Payload: "26.0"})

	time.Sleep(100 * time.Millisecond)
	d.Shutdown()
	fmt.Println("shutdown complete")
}
```

